import { aggregateCandles, summarize, evaluatePrice } from './pricing.js';
import { createPriceChart } from './chart.js';

const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = value => typeof value === 'number' && Number.isFinite(value) && value > 0 ? new Intl.NumberFormat('zh-CN',{style:'currency',currency:'CNY',maximumFractionDigits:2}).format(value) : '—';
const platformName = platform => ({jd:'京东',taobao:'淘宝',tmall:'天猫'}[platform] || platform || '商品页');
const dateText = value => value && Number.isFinite(Date.parse(value)) ? new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(value)) : '尚未采集';
const paths={chart:'<path d="M3 3v18h18M7 15l4-5 4 3 5-8"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',book:'<path d="M4 3h13a3 3 0 0 1 3 3v15H6a3 3 0 0 1 0-6h14M4 3v15M8 7h8M8 11h5"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',moon:'<path d="M20 15a8.5 8.5 0 0 1-11-11A8.5 8.5 0 1 0 20 15Z"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 8a2.5 2.5 0 1 1 4 2c-1 .5-1.5 1-1.5 3M12 17h.01"/>','chevron-down':'<path d="m6 9 6 6 6-6"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',refresh:'<path d="M20 7a9 9 0 1 0 1 8M20 3v5h-5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||''}</svg>`;
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
let theme='dark';try{theme=localStorage.getItem('pirce-watch:theme')==='light'?'light':'dark';}catch{}
const state={products:[],selected:null,loaded:false,loading:false,error:'',errors:{products:'',status:''},revision:0,targetSaving:false,view:'workbench',query:'',filter:'all',chartMode:'candles',period:'day',range:90,chart:null,chartFailed:false,theme,status:null,alerts:[],refreshing:false};
let toastTimer;
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
const extensionRequests=new Map();let extensionInstalled=false;
function askExtension(action,payload={},timeout=2000){const requestId=crypto.randomUUID();return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{extensionRequests.delete(requestId);reject(new Error('请在已安装扩展的 Chrome 中打开本页，刷新后再连接。'));},timeout);extensionRequests.set(requestId,{resolve,reject,timer});window.postMessage({type:`PIRCE_WATCH_${action}`,requestId,...payload},location.origin);});}
function checkExtension(){if(extensionInstalled)window.postMessage({type:'PIRCE_WATCH_CHECK',requestId:crypto.randomUUID()},location.origin);}
window.addEventListener('message',event=>{if(event.source!==window||event.origin!==location.origin)return;const data=event.data;if(data?.type==='PIRCE_WATCH_EXTENSION_READY'){extensionInstalled=true;return;}if(data?.type!=='PIRCE_WATCH_EXTENSION_RESPONSE')return;extensionInstalled=true;const pending=extensionRequests.get(data.requestId);if(pending){clearTimeout(pending.timer);extensionRequests.delete(data.requestId);data.ok?pending.resolve(data):pending.reject(new Error(data.error||'扩展连接失败。'));}if(data.action==='CHECK'){loadStatus();loadProducts();loadAlerts();}});
async function api(path,{method='GET',body}={}){
  const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),60000);
  try{
    const response=await fetch(path,{method,cache:'no-store',credentials:'same-origin',headers:{'Accept':'application/json',...(body!==undefined?{'Content-Type':'application/json'}:{})},body:body===undefined?undefined:JSON.stringify(body),signal:controller.signal});
    const payload=await response.json().catch(()=>{throw new Error('服务返回了无法读取的响应。');});
    if(!payload||typeof payload!=='object'||Array.isArray(payload))throw new Error('服务返回的数据格式不正确。');
    if(!response.ok)throw new Error(typeof payload.error==='string'?payload.error:payload.error?.message||payload.message||`请求失败（${response.status}）`);
    return payload;
  }catch(error){if(error.name==='AbortError')throw new Error('采集请求超时，请稍后刷新关注列表确认结果。');if(error instanceof TypeError)throw new Error('无法连接价格服务，请确认服务正在运行。');throw error;}finally{clearTimeout(timer);}
}
const selected=()=>state.products.find(p=>p.id===state.selected)||null;
const observations=product=>(Array.isArray(product?.samples)?product.samples:[]).filter(s=>typeof s.price==='number'&&Number.isFinite(s.price)&&s.price>0&&Number.isFinite(Date.parse(s.timestamp))&&(s.priceKind||'listed')===(product.priceKind||'listed')).slice().sort((a,b)=>Date.parse(a.timestamp)-Date.parse(b.timestamp));
function validURL(value){let url;try{url=new URL(value.trim());}catch{throw new Error('请输入完整商品链接，以 https:// 开头。');}if(!['http:','https:'].includes(url.protocol))throw new Error('请输入 http 或 https 商品链接。');return url.href;}
function applyTheme(){document.documentElement.dataset.theme=state.theme;$('theme-button').innerHTML=icon(state.theme==='dark'?'sun':'moon');$('theme-button').setAttribute('aria-label',`切换为${state.theme==='dark'?'浅':'深'}色模式`);}
function setView(view){state.view=['workbench','alerts','about'].includes(view)?view:'workbench';['workbench','alerts','about'].forEach(name=>$(name+'-view').hidden=name!==state.view);document.querySelectorAll('.nav-item[data-view]').forEach(el=>{const active=el.dataset.view===state.view;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});$('view-name').textContent={workbench:'价格监控',alerts:'目标价提醒',about:'使用说明'}[state.view];document.title=`Pirce Watch · ${$('view-name').textContent}`;if(view==='alerts')loadAlerts();}
function showServiceError(message,area='products'){state.errors[area]=message;const error=state.errors.products||state.errors.status;state.error=error;$('service-error').hidden=!error;$('service-error-text').textContent=error;$('service-status').textContent=error?'连接异常':state.status?.sourceState==='active'?'已取得实际报价':state.status?.sourceState==='waiting'?'等待首次报价':state.status?'服务已连接':'服务状态待确认';}
function renderWatchlist(){
  $('watch-count').textContent=state.products.length;
  const list=state.products.filter(p=>`${p.name||''} ${p.spec||''} ${p.url||''}`.toLowerCase().includes(state.query.toLowerCase())).filter(p=>state.filter!=='target'||Number.isFinite(p.target));
  $('product-list').innerHTML=list.length?list.map(p=>`<button class="product-item ${p.id===state.selected?'active':''}" data-product="${esc(p.id)}" aria-pressed="${p.id===state.selected}"><span class="mini-art">${icon('chart')}</span><span><strong>${esc(p.name||platformName(p.platform))}</strong><span class="item-category">${esc(platformName(p.platform))} · ${p.status==='ok'?'已采集':esc(({pending:'等待采集',blocked:'采集受限',unavailable:'暂无可用报价',error:'采集失败'})[p.status]||'等待采集')}</span></span><span class="item-price" title="最近有效报价">${money(p.price)}</span></button>`).join(''):`<div class="initial-loading">${!state.loaded?'尚未连接':state.query?'没有匹配的商品':state.filter==='target'?'还没有设置目标价':'暂无关注商品'}</div>`;
  document.querySelectorAll('[data-filter]').forEach(el=>{const active=el.dataset.filter===state.filter;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});
  $('nav-alert-count').textContent=state.alerts.length;
}
function renderOHLC(candle=null){const points=aggregateCandles(observations(selected()),state.period);const item=candle||points.at(-1);if(!item){$('hover-date').textContent='暂无记录';$('ohlc').textContent='';return;}$('hover-date').textContent=item.time;$('ohlc').innerHTML=['open','high','low','close'].map((key,i)=>`<span><em>${['开','高','低','收'][i]}</em> ${esc(money(item[key]))}</span>`).join('');}
function updateChart(){
  const product=selected();const samples=observations(product);
  if(!state.chart&&!state.chartFailed&&product){try{state.chart=createPriceChart($('price-chart'),{onHover:renderOHLC});}catch{state.chartFailed=true;}}
  if(state.chart)state.chart.update({candles:aggregateCandles(samples,state.period),mode:state.chartMode,period:state.period,target:product?.target??null,showAverage:$('average-toggle').checked,theme:state.theme});
  $('chart-empty-note').hidden=samples.length>0&&!state.chartFailed;
  $('chart-empty-note').textContent=state.chartFailed?'图表暂不可用，价格记录仍可在下方查看。':product?.status==='pending'?'等待首次成功采集':product?.statusMessage||'尚无可用价格记录';
  $('average-label').textContent=({day:'MA7',week:'MA7周',month:'MA7月'})[state.period];renderOHLC();
  document.querySelectorAll('[data-period]').forEach(el=>{const active=el.dataset.period===state.period;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});
  document.querySelectorAll('[data-chart-mode]').forEach(el=>{const active=el.dataset.chartMode===state.chartMode;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});
  document.querySelectorAll('[data-range]').forEach(el=>{const active=String(el.dataset.range)===String(state.range);el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});
}
function renderProduct(){
  const p=selected();$('product-workspace').hidden=!p;$('empty-view').hidden=!!p;
  if(!p){$('empty-title').textContent=state.errors.products?'无法连接价格服务':state.loaded?'添加第一个商品':'正在连接价格服务';$('empty-description').textContent=state.errors.products?'请重新连接，尚未读取关注列表。':state.loaded?'粘贴上方商品链接，开始积累价格记录。':'读取已关注的商品。';return;}
  const samples=observations(p);const stats=summarize(samples);const signal=evaluatePrice(samples,p.target);
  $('product-name').textContent=p.name||`${platformName(p.platform)}商品`;$('product-subtitle').textContent=p.spec||'';
  $('hero-price').textContent=money(p.price);
  $('price-kind').textContent=({advertised:'官方公开展示价',browser:'商品页显示价',listed:'公开标价',sku:'所选规格标价（优惠前）'})[p.priceKind]||'最近有效报价';
  const source=$('product-source');source.textContent=platformName(p.platform);try{source.href=validURL(p.url);}catch{source.removeAttribute('href');}
  $('collection-status').textContent=`${p.status==='ok'?(p.priceKind==='advertised'?'展示价已更新，结算价请在商品页核对':p.priceKind==='sku'?'已更新所选规格的优惠前标价':'采集成功'):p.statusMessage||({pending:'等待采集',blocked:'商品页限制访问',unavailable:'暂无可用报价',error:'采集失败'})[p.status]||'等待采集'}${p.lastCheckedAt?` · ${dateText(p.lastCheckedAt)}`:''}${p.status!=='ok'&&p.lastSuccessAt?` · 上次成功 ${dateText(p.lastSuccessAt)}`:''}`;
  $('collection-status').className=p.status==='ok'?'':'collection-warning';
  $('collection-source').textContent='';if(p.source){let sourceUrl;try{const u=new URL(p.sourceUrl);if(u.protocol==='https:'&&['item.jd.com','item.m.jd.com','p.3.cn','item.taobao.com','h5.m.taobao.com','detail.tmall.com','detail.m.tmall.com'].includes(u.hostname))sourceUrl=u.href;}catch{}if(sourceUrl){const link=document.createElement('a');link.href=sourceUrl;link.textContent=p.source;link.target='_blank';link.rel='noreferrer';$('collection-source').append(link);}else $('collection-source').textContent=p.source;}
  $('price-change').hidden=!Number.isFinite(stats.change);if(Number.isFinite(stats.change)){$('price-change').className=`price-change ${stats.change<=0?'green':'coral'}`;$('price-change').textContent=`${stats.change<=0?'↓':'↑'} ${money(Math.abs(stats.change))}${stats.change===0?'与上一记录日持平':' · 较上一记录日'}`;if(stats.change===0)$('price-change').textContent='与上一记录日持平';}
  $('record-low').textContent=money(stats.low);$('record-high').textContent=money(stats.high);$('record-average').textContent=money(stats.average);$('record-days').textContent=stats.dayCount?`${stats.dayCount} 天`:'—';
  const sufficient=stats.dayCount>=7;$('percentile').innerHTML=sufficient?`${stats.percentile.toFixed(1)}<small>%</small>`:'—';$('rank-fill').style.width=sufficient?`${stats.percentile}%`:'0';$('signal-title').textContent=signal.label;$('signal-description').textContent=sufficient?`${stats.percentile.toFixed(1)}% 的记录价低于末次报价。`:`已有 ${stats.sampleCount} 条记录，覆盖 ${stats.dayCount} 天。`;
  $('low-gap').innerHTML=`<span>距记录最低价</span><strong>${stats.current===null?'—':new Intl.NumberFormat('zh-CN',{style:'currency',currency:'CNY',maximumFractionDigits:2}).format(stats.current-stats.low)}</strong>`;
  if(document.activeElement!==$('target-price'))$('target-price').value=Number.isFinite(p.target)?p.target:'';
  $('target-submit-label').textContent=Number.isFinite(p.target)?'更新目标价':'保存目标价';$('remove-target').hidden=!Number.isFinite(p.target);
  $('target-status').textContent=Number.isFinite(p.target)?`${money(p.target)} · ${typeof p.price!=='number'||!Number.isFinite(p.price)||p.price<=0?'等待有效报价':p.price<=p.target?'末次有效报价已达到':'等待达到'}`:'成功取得报价后检查目标价。';
  $('refresh-product').disabled=state.refreshing;$('refresh-product').innerHTML=`${icon('refresh')}${state.refreshing?'正在采集…':'立即采集'}`;
  $('sample-count').textContent=samples.length>50?`最近50条 / 共${samples.length}条`:`${samples.length} 条`;$('samples-body').innerHTML=samples.length?samples.slice(-50).reverse().map(s=>`<tr><td>${esc(new Date(s.timestamp).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}))}</td><td class="price-number">${money(s.price)}</td></tr>`).join(''):'<tr><td colspan="2">尚无成功采集记录。</td></tr>';
  updateChart();
}
function render(){renderWatchlist();renderProduct();}
function upsert(product,existingOnly=false){if(!product?.id)throw new Error('服务未返回有效商品。');const index=state.products.findIndex(p=>p.id===product.id);if(index<0&&existingOnly)return false;state.revision+=1;if(index<0)state.products.unshift(product);else state.products[index]=product;return true;}
async function loadProducts(){if(state.loading)return;state.loading=true;const revision=state.revision;try{const payload=await api('/api/products');if(!Array.isArray(payload.products))throw new Error('服务返回的商品列表格式不正确。');if(revision!==state.revision)return;state.products=payload.products.filter(p=>p&&p.id&&p.watched!==false);state.loaded=true;if(!selected())state.selected=state.products[0]?.id??null;showServiceError('');render();}catch(error){showServiceError(error.message);render();}finally{state.loading=false;}}
async function loadStatus(){try{const status=await api('/api/status');if(status.mode!=='live')throw new Error('当前服务未提供真实采集模式。');state.status=status;$('open-browser').hidden=!status.extension;$('open-browser').textContent=status.extension?.connected?'浏览器已连接':'连接浏览器';$('about-status').textContent=status.note||`服务每${status.intervalMinutes}分钟尝试采集。`;showServiceError('','status');}catch(error){$('about-status').textContent=error.message;showServiceError(error.message,'status');}}
async function loadAlerts(){try{const payload=await api('/api/alerts');if(!Array.isArray(payload.alerts))throw new Error('提醒列表格式不正确。');state.alerts=payload.alerts;$('nav-alert-count').textContent=state.alerts.length;$('alerts-list').innerHTML=state.alerts.length?state.alerts.slice().reverse().map(a=>`<article class="panel alert-card"><div class="alert-info"><h3>${esc(a.name)}</h3><p>${esc(dateText(a.timestamp))} · 目标 ${money(a.target)}</p></div><strong class="alert-value">${money(a.price)}</strong><span class="alert-status hit">已到价</span><button class="button secondary" data-alert-product="${esc(a.productId)}">查看商品</button></article>`).join(''):'<div class="panel empty-state"><h2>暂无到价记录</h2><p>为关注商品设置目标价，后台采集后自动检查。</p></div>';}catch(error){$('alerts-list').innerHTML=`<div class="panel empty-state"><h2>提醒读取失败</h2><p>${esc(error.message)}</p><button class="button secondary" data-retry-alerts>重试</button></div>`;}}
async function addProduct(form,urlInput,errorElement,name='',spec=''){
  if(form.getAttribute('aria-busy')==='true')return;errorElement.textContent='';urlInput.removeAttribute('aria-invalid');let url;try{url=validURL(urlInput.value);}catch(error){errorElement.textContent=error.message;urlInput.setAttribute('aria-invalid','true');urlInput.focus();return;}
  const button=form.querySelector('button[type="submit"]');const previous=button.textContent;button.disabled=true;form.setAttribute('aria-busy','true');button.textContent='正在采集…';
  try{const payload=await api('/api/products',{method:'POST',body:{url,...(name.trim()?{name:name.trim()}:{}),...(spec.trim()?{spec:spec.trim()}:{})}});upsert(payload.product);state.selected=payload.product.id;state.loaded=true;state.filter='all';state.query='';$('search').value='';form.reset();$('catalog-dialog').close();setView('workbench');showServiceError('');render();toast(payload.duplicate?'已打开已关注的商品':payload.product.status==='ok'?'已添加并获取报价':'已添加，等待可用报价');loadAlerts();checkExtension();}catch(error){errorElement.textContent=error.message;}finally{button.disabled=false;form.removeAttribute('aria-busy');button.textContent=previous;}
}
function openAdd(){if($('quick-add-url').value)$('add-product-url').value=$('quick-add-url').value;$('add-product-error').textContent='';$('catalog-dialog').showModal();$('add-product-url').focus();}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.view)setView(button.dataset.view);if(button.dataset.product){state.selected=button.dataset.product;render();}if(button.dataset.filter){state.filter=button.dataset.filter;renderWatchlist();}if(button.dataset.chartMode){state.chartMode=button.dataset.chartMode;updateChart();}if(button.dataset.range){state.range=button.dataset.range==='all'?'all':Number(button.dataset.range);state.chart?.setRange(state.range);updateChart();}if(button.dataset.alertProduct){if(state.products.some(p=>p.id===button.dataset.alertProduct)){state.selected=button.dataset.alertProduct;setView('workbench');render();}else toast('这个商品已不在关注列表中。');}if(button.hasAttribute('data-retry-alerts'))loadAlerts();});
$('search').addEventListener('input',event=>{state.query=event.target.value.trim();renderWatchlist();});
$('quick-add-form').addEventListener('submit',event=>{event.preventDefault();addProduct(event.currentTarget,$('quick-add-url'),$('quick-add-error'));});
$('add-product-form').addEventListener('submit',event=>{event.preventDefault();addProduct(event.currentTarget,$('add-product-url'),$('add-product-error'),$('add-product-name').value,$('add-product-spec').value);});
$('browse-button').addEventListener('click',openAdd);$('open-catalog').addEventListener('click',openAdd);$('close-catalog').addEventListener('click',()=>$('catalog-dialog').close());
$('open-browser').addEventListener('click',()=>{$('browser-message').textContent=state.status?.extension?.connected?'扩展已连接，浏览器运行时会自动检查关注商品。':'';$('browser-dialog').showModal();});
$('close-browser').addEventListener('click',()=>$('browser-dialog').close());
$('browser-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button[type="submit"]');button.disabled=true;$('browser-message').textContent='正在连接…';try{await askExtension('STATUS');const {code}=await api('/api/extension/pair',{method:'POST',body:{}});await askExtension('PAIR',{code},6000);$('browser-message').textContent='已连接。可以添加商品链接，价格会自动采集。';await loadStatus();checkExtension();toast('浏览器扩展已连接');}catch(error){$('browser-message').textContent=error.message;}finally{button.disabled=false;}});
$('refresh-product').addEventListener('click',async()=>{const product=selected();if(!product||state.refreshing)return;state.refreshing=true;renderProduct();try{const payload=await api(`/api/products/${encodeURIComponent(product.id)}/refresh`,{method:'POST',body:{}});if(!upsert(payload.product,true))return;render();toast(payload.product.status==='ok'?'采集完成':payload.product.statusMessage||'本次未获取可用报价');loadAlerts();checkExtension();}catch(error){if(state.selected===product.id)$('collection-status').textContent=error.message;toast(error.message);}finally{state.refreshing=false;$('refresh-product').disabled=false;$('refresh-product').innerHTML=`${icon('refresh')}立即采集`;}});
$('delete-product').addEventListener('click',async()=>{const product=selected();if(!product)return;$('delete-product').disabled=true;try{await api(`/api/products/${encodeURIComponent(product.id)}`,{method:'DELETE'});state.revision+=1;state.products=state.products.filter(p=>p.id!==product.id);state.selected=state.products[0]?.id??null;render();toast('已删除关注');loadAlerts();}catch(error){toast(error.message);}finally{$('delete-product').disabled=false;}});
$('target-form').addEventListener('submit',async event=>{event.preventDefault();const p=selected();if(!p||state.targetSaving)return;const price=Number($('target-price').value);if(!Number.isFinite(price)||price<0.01||price>10000000){$('target-error').textContent='请输入 0.01 至 10,000,000 之间的目标价。';return;}$('target-error').textContent='';const button=event.currentTarget.querySelector('button[type="submit"]');state.targetSaving=true;button.disabled=true;$('remove-target').disabled=true;try{const payload=await api(`/api/products/${encodeURIComponent(p.id)}/target`,{method:'POST',body:{price:Math.round(price*100)/100}});if(!upsert(payload.product,true))return;render();toast('目标价已保存');loadAlerts();}catch(error){if(state.selected===p.id)$('target-error').textContent=error.message;else toast(error.message);}finally{state.targetSaving=false;button.disabled=false;$('remove-target').disabled=false;}});
$('remove-target').addEventListener('click',async()=>{const p=selected();if(!p||state.targetSaving)return;state.targetSaving=true;const button=$('target-form').querySelector('button[type="submit"]');button.disabled=true;$('remove-target').disabled=true;try{const payload=await api(`/api/products/${encodeURIComponent(p.id)}/target`,{method:'POST',body:{price:null}});if(!upsert(payload.product,true))return;render();toast('目标价已移除');}catch(error){if(state.selected===p.id)$('target-error').textContent=error.message;else toast(error.message);}finally{state.targetSaving=false;button.disabled=false;$('remove-target').disabled=false;}});
document.querySelectorAll('[data-period]').forEach(button=>button.addEventListener('click',()=>{state.period=button.dataset.period;updateChart();}));$('average-toggle').addEventListener('change',updateChart);$('chart-fit').addEventListener('click',()=>{state.range='all';state.chart?.fit();updateChart();});
$('theme-button').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';try{localStorage.setItem('pirce-watch:theme',state.theme);}catch{}applyTheme();if(selected())updateChart();});$('help-button').addEventListener('click',()=>setView('about'));
$('retry-service').addEventListener('click',()=>{loadStatus();loadProducts();loadAlerts();});
$('download-data').addEventListener('click',()=>{const p=selected();if(!p)return;const data={name:p.name,spec:p.spec,url:p.url,platform:p.platform,source:p.source,samples:observations(p)};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`pirce-watch-${String(p.id).replace(/[^a-zA-Z0-9_-]/g,'')}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('catalog-dialog').open){event.preventDefault();$('search').focus();}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){loadProducts();loadAlerts();}});
setInterval(()=>{if(!document.hidden){loadStatus();loadProducts();loadAlerts();}},5000);
askExtension('STATUS').catch(()=>{});
hydrateIcons();applyTheme();setView('workbench');loadStatus();loadProducts();loadAlerts();
